import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.DJVIMu25.js";const n=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{"title":"命令与权限"},"headers":[],"relativePath":"zh_Hans/guides/commands.md","filePath":"zh_Hans/guides/commands.md","lastUpdated":1786543805000}'),c={name:"zh_Hans/guides/commands.md"};function r(g,t,m,b,s,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>JoyMart 提供玩家命令与管理命令两套体系，全部通过权限节点控制。命令相关的全局开关与子命令配置见 <a href="./configuration">配置文件说明</a>。</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to &quot;玩家命令&quot;">​</a></h2><p>默认 <code>/gamebox</code>，简写 <code>/gb</code>。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/gamebox</code></td><td><code>gamebox.use</code></td><td>打开主菜单</td></tr><tr><td><code>/gamebox &lt;子命令&gt;</code></td><td><code>gamebox.play.&lt;id&gt;</code></td><td>直接进入指定游戏（子命令见 <code>games.yml</code>）</td></tr><tr><td><code>/gamebox token</code></td><td><code>gamebox.use</code></td><td>查看自己代币余额</td></tr><tr><td><code>/gamebox info</code></td><td><code>gamebox.use</code></td><td>查看插件信息</td></tr><tr><td><code>/gamebox help</code></td><td><code>gamebox.use</code></td><td>查看帮助</td></tr><tr><td><code>/gamebox accept [玩家]</code></td><td><code>gamebox.use</code></td><td>接受对战邀请</td></tr><tr><td><code>/gamebox decline [玩家]</code></td><td><code>gamebox.use</code></td><td>拒绝对战邀请</td></tr></tbody></table><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to &quot;管理命令&quot;">​</a></h2><p>默认 <code>/gameboxadmin</code>，简写 <code>/gba</code>。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/gba reload</code></td><td><code>gamebox.admin.reload</code></td><td>重载所有配置</td></tr><tr><td><code>/gba tokens &lt;玩家&gt; get</code></td><td><code>gamebox.admin.tokens</code></td><td>查看玩家代币</td></tr><tr><td><code>/gba tokens &lt;玩家&gt; set &lt;数量&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>设置玩家代币</td></tr><tr><td><code>/gba tokens &lt;玩家&gt; give &lt;数量&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>给予玩家代币</td></tr><tr><td><code>/gba tokens &lt;玩家&gt; take &lt;数量&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>扣除玩家代币</td></tr><tr><td><code>/gba games &lt;游戏&gt; &lt;enable|disable&gt;</code></td><td><code>gamebox.admin.games</code></td><td>开关某款游戏</td></tr><tr><td><code>/gba games</code></td><td><code>gamebox.admin.games</code></td><td>打开游戏管理 GUI（开关游戏、编辑彩票/抽奖机奖项池）</td></tr><tr><td><code>/gba language</code></td><td><code>gamebox.admin.language</code></td><td>检查语言文件完整性</td></tr><tr><td><code>/gba migrate &lt;file|mysql&gt;</code></td><td><code>gamebox.admin.migrate</code></td><td>在 YAML/MySQL 之间迁移数据</td></tr><tr><td><code>/gba reset &lt;游戏&gt;</code></td><td><code>gamebox.admin.reset</code></td><td>重置某游戏的高分榜</td></tr><tr><td><code>/gba shop</code></td><td><code>gamebox.admin.shop</code></td><td>打开商店管理 GUI（上架/下架物品）</td></tr></tbody></table><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限节点</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>gamebox.use</code></td><td>true</td><td>使用 <code>/gamebox</code> 主命令</td></tr><tr><td><code>gamebox.play.*</code></td><td>true</td><td>游玩所有游戏</td></tr><tr><td><code>gamebox.play.&lt;id&gt;</code></td><td>true</td><td>游玩指定游戏（如 <code>gamebox.play.2048</code>）</td></tr><tr><td><code>gamebox.gamegui.&lt;id&gt;</code></td><td>true</td><td>在主菜单看到指定游戏的图标</td></tr><tr><td><code>gamebox.admin.*</code></td><td>op</td><td>所有管理权限</td></tr><tr><td><code>gamebox.admin.shop</code></td><td>op</td><td>通过 GUI 上架/下架商店物品</td></tr><tr><td><code>gamebox.shop.&lt;custom&gt;</code></td><td>false</td><td>商店商品的购买权限（在 <code>tokenShop.yml</code> 中按商品定义）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">权限自动注册</p><p>每个游戏在加载时会自动注册对应的 <code>gamebox.play.&lt;id&gt;</code> 和 <code>gamebox.gamegui.&lt;id&gt;</code> 权限（默认 true）。商店商品的 <code>buyPermission</code> 不会自动注册，请用你的权限插件（如 LuckPerms）分配。</p></div>',11)])])}const h=d(c,[["render",r]]);export{n as __pageData,h as default};
